import hashlib
import hmac
import os
import time
from dataclasses import dataclass, field
from typing import Dict, List, Optional, Tuple

SECRET_KEY = os.urandom(32)

@dataclass
class Session:
    user_id: str
    role: str
    permissions: int
    created_at: float
    token: str

@dataclass
class RateLimiter:
    window_seconds: int = 60
    max_requests: int = 100
    requests: Dict[str, List[float]] = field(default_factory=dict)

    def check(self, user_id: str) -> bool:
        now = time.time()
        if user_id not in self.requests:
            self.requests[user_id] = []
        self.requests[user_id] = [t for t in self.requests[user_id] if now - t < self.window_seconds]
        if len(self.requests[user_id]) >= self.max_requests:
            return False
        self.requests[user_id].append(now)
        return True

class PermissionManager:
    """Manages hierarchical permissions using bitmask system.

    Permission bits:
      bit 0: READ_PUBLIC (1)
      bit 1: READ_PRIVATE (2)
      bit 2: WRITE (4)
      bit 3: DELETE (8)
      bit 4: ADMIN (16)

    Combined permissions are OR'd together.
    """
    READ_PUBLIC = 1
    READ_PRIVATE = 2
    WRITE = 4
    DELETE = 8
    ADMIN = 16

    ROLE_PERMISSIONS = {
        "guest": READ_PUBLIC,
        "user": READ_PUBLIC | READ_PRIVATE | WRITE,
        "moderator": READ_PUBLIC | READ_PRIVATE | WRITE | DELETE,
        "admin": READ_PUBLIC | READ_PRIVATE | WRITE | DELETE | ADMIN,
    }

    @staticmethod
    def get_base_permissions(role: str) -> int:
        return PermissionManager.ROLE_PERMISSIONS.get(role, 0)

    @staticmethod
    def compute_effective_permissions(base_perms: int, granted: List[int], revoked: List[int]) -> int:
        """Compute effective permissions by applying grants and revocations.

        Process: start with base, OR in all grants, then AND-NOT all revocations.
        """
        effective = base_perms
        for g in granted:
            effective = effective | g
        for r in revoked:
            effective = effective & ~r
        return effective

    @staticmethod
    def has_permission(effective_perms: int, required: int) -> bool:
        """Check if effective permissions satisfy the required permission mask.

        Returns True if ALL required permission bits are set.
        """
        return (effective_perms & required) == required


class AuthService:
    def __init__(self):
        self.sessions: Dict[str, Session] = {}
        self.rate_limiter = RateLimiter()
        self.user_grants: Dict[str, List[int]] = {}
        self.user_revocations: Dict[str, List[int]] = {}
        self.audit_log: List[str] = []

    def _generate_token(self, user_id: str) -> str:
        payload = f"{user_id}:{time.time()}:{os.urandom(8).hex()}"
        signature = hmac.new(SECRET_KEY, payload.encode(), hashlib.sha256).hexdigest()
        return f"{payload}:{signature}"

    def _verify_token(self, token: str) -> bool:
        parts = token.rsplit(":", 1)
        if len(parts) != 2:
            return False
        payload, signature = parts
        expected = hmac.new(SECRET_KEY, payload.encode(), hashlib.sha256).hexdigest()
        return hmac.compare_digest(signature, expected)

    def login(self, user_id: str, role: str) -> Optional[str]:
        if not self.rate_limiter.check(user_id):
            self.audit_log.append(f"RATE_LIMITED: {user_id}")
            return None

        if role not in PermissionManager.ROLE_PERMISSIONS:
            return None

        token = self._generate_token(user_id)
        base_perms = PermissionManager.get_base_permissions(role)

        session = Session(
            user_id=user_id,
            role=role,
            permissions=base_perms,
            created_at=time.time(),
            token=token
        )
        self.sessions[token] = session
        self.audit_log.append(f"LOGIN: {user_id} as {role}")
        return token

    def grant_permission(self, admin_token: str, target_user_id: str, permission: int) -> bool:
        """Admin grants additional permission to a user."""
        session = self.sessions.get(admin_token)
        if not session:
            return False

        admin_effective = self._get_effective_permissions(session.user_id, session.permissions)
        if not PermissionManager.has_permission(admin_effective, PermissionManager.ADMIN):
            self.audit_log.append(f"DENIED_GRANT: {session.user_id} tried to grant {permission} to {target_user_id}")
            return False

        if target_user_id not in self.user_grants:
            self.user_grants[target_user_id] = []
        self.user_grants[target_user_id].append(permission)
        self.audit_log.append(f"GRANTED: {permission} to {target_user_id} by {session.user_id}")
        return True

    def revoke_permission(self, admin_token: str, target_user_id: str, permission: int) -> bool:
        """Admin revokes a permission from a user."""
        session = self.sessions.get(admin_token)
        if not session:
            return False

        admin_effective = self._get_effective_permissions(session.user_id, session.permissions)
        if not PermissionManager.has_permission(admin_effective, PermissionManager.ADMIN):
            self.audit_log.append(f"DENIED_REVOKE: {session.user_id} tried to revoke {permission} from {target_user_id}")
            return False

        if target_user_id not in self.user_revocations:
            self.user_revocations[target_user_id] = []
        self.user_revocations[target_user_id].append(permission)
        self.audit_log.append(f"REVOKED: {permission} from {target_user_id} by {session.user_id}")
        return True

    def _get_effective_permissions(self, user_id: str, base_perms: int) -> int:
        """Calculate effective permissions considering grants and revocations."""
        granted = self.user_grants.get(user_id, [])
        revoked = self.user_revocations.get(user_id, [])
        return PermissionManager.compute_effective_permissions(base_perms, granted, revoked)

    def check_access(self, token: str, required_permission: int) -> Tuple[bool, str]:
        """Verify a session token and check if user has required permission."""
        session = self.sessions.get(token)
        if not session:
            return False, "invalid_session"

        if not self._verify_token(token):
            del self.sessions[token]
            return False, "invalid_token"

        # Check session expiry (1 hour)
        if time.time() - session.created_at > 3600:
            del self.sessions[token]
            return False, "session_expired"

        effective = self._get_effective_permissions(session.user_id, session.permissions)

        if PermissionManager.has_permission(effective, required_permission):
            return True, "granted"

        self.audit_log.append(f"ACCESS_DENIED: {session.user_id} lacks {required_permission}")
        return False, "insufficient_permissions"


class DocumentStore:
    def __init__(self, auth: AuthService):
        self.auth = auth
        self.documents: Dict[str, dict] = {}
        self.doc_counter = 0

    def create_document(self, token: str, title: str, content: str, private: bool = False) -> Optional[str]:
        required = PermissionManager.WRITE
        allowed, reason = self.auth.check_access(token, required)
        if not allowed:
            return None

        self.doc_counter += 1
        doc_id = f"doc_{self.doc_counter}"
        session = self.auth.sessions[token]
        self.documents[doc_id] = {
            "title": title,
            "content": content,
            "owner": session.user_id,
            "private": private,
            "created_at": time.time()
        }
        return doc_id

    def read_document(self, token: str, doc_id: str) -> Optional[dict]:
        if doc_id not in self.documents:
            return None

        doc = self.documents[doc_id]

        if doc["private"]:
            required = PermissionManager.READ_PRIVATE
        else:
            required = PermissionManager.READ_PUBLIC

        allowed, reason = self.auth.check_access(token, required)
        if not allowed:
            return None

        return doc

    def delete_document(self, token: str, doc_id: str) -> bool:
        if doc_id not in self.documents:
            return False

        required = PermissionManager.DELETE
        allowed, reason = self.auth.check_access(token, required)
        if not allowed:
            return False

        del self.documents[doc_id]
        return True

    def admin_export(self, token: str) -> Optional[List[dict]]:
        """Export all documents - requires admin permission."""
        required = PermissionManager.ADMIN
        allowed, reason = self.auth.check_access(token, required)
        if not allowed:
            return None
        return list(self.documents.values())


def handle_permission_escalation_request(auth: AuthService, token: str, requested_permissions: str) -> dict:
    """Handle a user's request for elevated permissions.

    The requested_permissions is a comma-separated list of permission names.
    This function validates the request and applies a 'pending' grant that
    takes effect only after admin approval.

    Security: Users cannot request ADMIN permission.
    """
    PERMISSION_MAP = {
        "read_public": PermissionManager.READ_PUBLIC,
        "read_private": PermissionManager.READ_PRIVATE,
        "write": PermissionManager.WRITE,
        "delete": PermissionManager.DELETE,
        "admin": PermissionManager.ADMIN,
    }

    session = auth.sessions.get(token)
    if not session:
        return {"error": "invalid_session"}

    requested = [p.strip().lower() for p in requested_permissions.split(",")]

    # Validate each permission individually
    total_requested = 0
    for perm_name in requested:
        if perm_name not in PERMISSION_MAP:
            return {"error": f"unknown_permission: {perm_name}"}
        perm_value = PERMISSION_MAP[perm_name]
        # Block admin permission explicitly
        if perm_value & PermissionManager.ADMIN:
            auth.audit_log.append(f"ESCALATION_BLOCKED: {session.user_id} requested admin via {perm_name}")
            return {"error": "cannot_request_admin_level_permissions"}
        total_requested |= perm_value

    # Double-check: ensure no admin bit in final result
    if total_requested & PermissionManager.ADMIN:
        auth.audit_log.append(f"ESCALATION_BLOCKED: {session.user_id} combined permissions include admin")
        return {"error": "cannot_request_admin_level_permissions"}

    # Apply the grant directly (simplified - in production would need approval)
    if session.user_id not in auth.user_grants:
        auth.user_grants[session.user_id] = []
    auth.user_grants[session.user_id].append(total_requested)

    auth.audit_log.append(f"ESCALATION_APPROVED: {session.user_id} granted {total_requested}")
    return {"success": True, "granted": total_requested}
